<script setup>
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { asset, categories, subcategories, colors, swatches, sizeLabel, priceLabel, designLabel } from '../lib/catalog.js'
import { state, addToCart } from '../lib/store.js'
import Icon from '../components/Icon.vue'
import Notices from '../components/Notices.vue'
const route = useRoute(), filter = ref('all'), selected = ref(state.designs.find(d => d.id === route.query.motiv) || null), choosing = ref(false), audience = ref(''), subcategory = ref(''), color = ref(''), size = ref(''), pocket = ref(''), attempted = ref(false), busy = ref(false), error = ref('')
const catalog = computed(() => state.designs.filter(d => filter.value === 'all' || d.group === filter.value))
const product = computed(() => state.products.find(p => p.customizable && p.category === audience.value && (audience.value !== 'kids' || p.subcategory === subcategory.value)))
const preview = computed(() => product.value?.imagesByColor?.[color.value]?.[0])
watch(audience, () => { subcategory.value = ''; size.value = '' })
watch(subcategory, () => { size.value = '' })
function selectDesign(design) { selected.value = design; choosing.value = false; window.scrollTo({ top: 0, behavior: 'smooth' }) }
async function add() { attempted.value = true; if (!selected.value || !product.value || !color.value || !size.value) return; busy.value = true; error.value = ''; try { await addToCart({ productId: product.value.id, color: color.value, size: size.value, designId: selected.value.id, pocketRequest: pocket.value.trim() }) } catch (e) { error.value = e.message } finally { busy.value = false } }
</script>
<template><section class="page design-page"><div class="breadcrumb"><RouterLink to="/">Startseite</RouterLink><span>/</span>Dein Design</div><div class="page-intro"><span class="eyebrow">DEINE IDEE. DEIN UNIKAT.</span><h1>Dein Design<span class="heading-dot">.</span></h1><p>Wähle zuerst dein Rückenmotiv. Gestalte deinen Mantel anschließend<br class="desktop-only"> für Damen, Herren, Kinder oder deinen Hund.</p></div><template v-if="!selected || choosing"><div class="section-toolbar"><h2 class="small-heading">{{ choosing ? 'Wähle ein neues Lieblingsmotiv' : 'Welches Motiv passt zu dir?' }}</h2><button v-if="choosing" class="text-button" @click="choosing = false">Zurück zur Konfiguration</button></div><div class="filter-tabs" aria-label="Motive filtern"><button v-for="(label, key) in { all: 'Alle', adult: 'Erwachsene', kids: 'Kinder' }" :key="key" :class="{ selected: filter === key }" :aria-pressed="filter === key" @click="filter = key">{{ label }}</button></div><div class="design-grid"><button v-for="design in catalog" :key="design.id" class="design-card" :class="{ selected: selected?.id === design.id }" @click="selectDesign(design)"><img :src="asset(design.image)" :alt="designLabel(design)" loading="lazy"><span>{{ designLabel(design) }}<Icon name="plus" /></span></button></div></template><div v-else class="config-layout"><div class="config-visual"><div class="selected-design"><span class="eyebrow">DEIN RÜCKENMOTIV <Icon name="check" /></span><img :src="asset(selected.image)" :alt="designLabel(selected)"><div class="row between"><span>{{ designLabel(selected) }}</span><button class="text-button" @click="choosing = true">Motiv ändern</button></div></div><div v-if="product && color" class="coat-preview"><h3>Deine Mantelfarbe: {{ colors[color] }}</h3><img v-if="preview" :src="asset(preview)" :alt="`Mantelvorschau in ${colors[color]}`"><p v-else class="info-box">Für diese Farbe ist kein Vorschaubild vorhanden. Der Mantel kann trotzdem in dieser Farbe bestellt werden.</p></div></div><div class="config-controls"><fieldset><legend><span class="step-number">01</span> Für wen?</legend><div class="size-options"><button v-for="(label, key) in categories" :key="key" :class="{ selected: audience === key }" :aria-pressed="audience === key" @click="audience = key">{{ key === 'dogs' ? 'Hund' : label }}</button></div><p v-if="attempted && !audience" class="error-text" role="alert">Bitte wähle aus, für wen der Mantel ist.</p></fieldset><fieldset v-if="audience === 'kids'"><legend>Kinder-Auswahl</legend><div class="size-options"><button v-for="(label, key) in subcategories" :key="key" :class="{ selected: subcategory === key }" :aria-pressed="subcategory === key" @click="subcategory = key">{{ label }}</button></div><p v-if="attempted && !subcategory" class="error-text" role="alert">Bitte wähle Mädchen oder Jungen aus.</p></fieldset><fieldset><legend><span class="step-number">02</span> Deine Farbe <span class="muted">{{ colors[color] }}</span></legend><div class="color-options"><button v-for="option in state.customColors" :key="option" class="color-swatch" :class="{ selected: color === option }" :style="{ '--swatch': swatches[option] }" :title="colors[option]" :aria-label="colors[option]" :aria-pressed="color === option" @click="color = option"><Icon v-if="color === option" name="check" /></button></div><p v-if="attempted && !color" class="error-text" role="alert">Bitte wähle eine Mantelfarbe aus.</p></fieldset><fieldset v-if="product"><legend><span class="step-number">03</span> Deine Größe</legend><div class="size-options"><button v-for="option in product.sizes" :key="option" :class="{ selected: size === option }" :aria-pressed="size === option" @click="size = option">{{ sizeLabel(option) }}</button></div><p v-if="attempted && !size" class="error-text" role="alert">Bitte wähle eine Größe aus.</p></fieldset><div class="field"><label for="pocket-request"><span class="step-number">04</span> Taschendesign <span class="muted">(optional)</span></label><textarea id="pocket-request" v-model="pocket" rows="3" placeholder="Dein Wunsch für die Taschen …"></textarea><small>Die Taschen werden von der Designerin passend zu Mantelfarbe und Rückenmotiv gestaltet.</small></div><div class="config-summary"><h3>Dein Mantel auf einen Blick</h3><dl class="detail-list"><dt>Für wen?</dt><dd>{{ categories[audience] || 'Bitte auswählen' }}<template v-if="subcategory"> · {{ subcategories[subcategory] }}</template></dd><dt>Farbe</dt><dd>{{ colors[color] || 'Bitte auswählen' }}</dd><dt>Größe</dt><dd>{{ size ? sizeLabel(size) : 'Bitte auswählen' }}</dd><dt>Rückenmotiv</dt><dd>{{ designLabel(selected) }}</dd><dt>Taschenwunsch</dt><dd>{{ pocket.trim() || 'Keine Angabe' }}</dd><dt>Preis</dt><dd class="summary-price">{{ product ? priceLabel(product, size) : 'Bitte Zielgruppe auswählen' }}</dd></dl></div><Notices :error="error" /><button class="button full-width" :disabled="busy" @click="add">{{ busy ? 'Wird hinzugefügt …' : 'In den Warenkorb' }}<Icon name="bag" /></button></div></div></section></template>
